import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const AllListings = () => {
  const userId = sessionStorage.getItem("userId");
  const [listings, setListings] = useState([]);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/listings/with-usernames`)
      .then((res) => res.json())
      .then((data) => setListings(data))
      .catch((err) => console.error("Error fetching listings:", err));
  }, []);

  const handleAddToCart = async (item) => {
    const res = await fetch(`${API_BASE_URL}/api/cart`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id: userId,
        listing_id: item.id,
      }),
    });

    if (res.ok) {
      alert("Item added to cart!");
    } else {
      alert("Failed to add item to cart.");
    }
  };

  const handleReportUser = async (reportedUserId) => {
    const reason = prompt("Why are you reporting this user?");
    if (!reason) return;

    const res = await fetch(`${API_BASE_URL}/api/user-reports`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        reported_user_id: reportedUserId,
        reporting_user_id: userId,
        reason,
      }),
    });

    if (res.ok) {
      alert("Report submitted.");
    } else {
      alert("Failed to submit report.");
    }
  };

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="dashboard-main" style={{ minHeight: "100vh", padding: "32px 48px" }}>
        <h2 style={{ textAlign: "center", marginBottom: "32px" }}>All Listings</h2>

        <div className="item-grid">
          {listings.length > 0 ? (
            listings
              .filter((item) => parseInt(item.user_id) !== parseInt(userId)) // show only other users' listings
              .map((item) => (
                <div className="item-card" key={item.id}>
                  <div className="image-placeholder">
                    {item.image ? <img src={item.image} alt={item.title} /> : <span>No Image</span>}
                  </div>
                  <h4>{item.title}</h4>
                  <p><strong>Seller:</strong> {item.username}</p>
                  <p>{item.description}</p>
                  <p><strong>Condition:</strong> {item.condition}</p>
                  <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                  <button onClick={() => handleAddToCart(item)} className="buy-btn">
                    🛒 Buy
                  </button>
                  <button onClick={() => handleReportUser(item.user_id)} className="report-btn">
                    🚩 Report User
                  </button>
                </div>
              ))
          ) : (
            <p style={{ textAlign: "center" }}>No listings available at the moment.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default AllListings;
